(function () {
  const cw = W, ch = H;

  function hash2(x, y) {
    let n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
    return n - Math.floor(n);
  }
  function smooth(t) { return t * t * (3 - 2 * t); }
  function noise2(x, y) {
    const xi = Math.floor(x), yi = Math.floor(y);
    const xf = x - xi, yf = y - yi;
    const a = hash2(xi, yi), b = hash2(xi + 1, yi);
    const c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
    const u = smooth(xf), v = smooth(yf);
    return a * (1 - u) * (1 - v) + b * u * (1 - v) + c * (1 - u) * v + d * u * v;
  }
  function fbm(x, y, oct) {
    let s = 0, amp = 0.5, f = 1;
    for (let i = 0; i < oct; i++) {
      s += amp * noise2(x * f, y * f);
      f *= 2.03; amp *= 0.5;
    }
    return s;
  }

  // ---------------- opaque backdrop ----------------
  ctx.fillStyle = '#2a2417';
  ctx.fillRect(0, 0, cw, ch);

  // warm glowing opening
  let bg = ctx.createRadialGradient(cw * 0.52, ch * 0.20, 40, cw * 0.52, ch * 0.32, ch * 0.85);
  bg.addColorStop(0, '#fbe6b0');
  bg.addColorStop(0.25, '#e9c98a');
  bg.addColorStop(0.55, '#a58a55');
  bg.addColorStop(1, '#4a3a22');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, cw, ch);

  // ---------------- distant hazy forest (no straight seam) ----------------
  // unfocused far trunks fading into the glow, drawn with irregular tapering
  function drawDistantTrunk(cx, baseY, topY, w, alpha, shade) {
    ctx.save();
    ctx.globalAlpha = alpha;
    const g = ctx.createLinearGradient(cx - w / 2, 0, cx + w / 2, 0);
    const r = Math.round(110 * shade + 60), gg = Math.round(88 * shade + 48), b = Math.round(52 * shade + 28);
    g.addColorStop(0, `rgb(${r + 30},${gg + 24},${b + 14})`);
    g.addColorStop(0.5, `rgb(${r},${gg},${b})`);
    g.addColorStop(1, `rgb(${r - 24},${gg - 18},${b - 8})`);
    ctx.fillStyle = g;
    ctx.beginPath();
    const N = 10;
    let lx = [];
    let rx = [];
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const y = baseY + (topY - baseY) * t;
      const taper = w * (1 - t * 0.55);
      const wob = Math.sin(t * 4.3 + cx * 0.02) * w * 0.4;
      const ccx = cx + wob;
      lx.push(ccx - taper / 2 + (hash2(i * 1.7, cx) - 0.5) * w * 0.15);
      rx.push(ccx + taper / 2 + (hash2(i * 2.1, cx + 5) - 0.5) * w * 0.15);
    }
    for (let i = 0; i < lx.length; i++) {
      if (i === 0) ctx.moveTo(lx[i], baseY + (topY - baseY) * (i / N));
      else ctx.lineTo(lx[i], baseY + (topY - baseY) * (i / N));
    }
    for (let i = rx.length - 1; i >= 0; i--) {
      ctx.lineTo(rx[i], baseY + (topY - baseY) * (i / N));
    }
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  for (let i = 0; i < 22; i++) {
    const cx = 80 + rand() * (cw - 160);
    const w = 6 + rand() * 22;
    const topY = ch * 0.02 + rand() * ch * 0.35;
    const baseY = ch * 0.55 + rand() * ch * 0.3;
    const a = 0.18 + rand() * 0.28;
    drawDistantTrunk(cx, baseY, topY, w, a, 0.5 + rand() * 0.4);
  }

  // distant canopy haze blobs — soft amber mottling, uneven
  for (let i = 0; i < 70; i++) {
    const x = rand() * cw, y = rand() * ch * 0.55;
    const r = 40 + rand() * 110;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(${220}, ${165 + rand() * 40}, ${85 + rand() * 25}, 0.13)`);
    g.addColorStop(1, `rgba(${220}, ${170}, ${90}, 0)`);
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  }

  // ---------------- stream: winding, with two bends ----------------
  // param t from 0 (far, near opening) to 1 (near, bottom)
  function streamCenter(t) {
    // two bends: gentle left then toward viewer right then left again
    const bend1 = Math.sin(t * Math.PI * 1.6 + 0.3) * cw * 0.10;
    const bend2 = Math.sin(t * Math.PI * 3.2 + 1.2) * cw * 0.045;
    return cw * 0.52 + bend1 * (1 - t * 0.4) + bend2 * (1 - t * 0.3);
  }
  function streamHalf(t) {
    // narrow at distance, widening near viewer; slight width modulation
    return 6 + t * t * 240 + Math.sin(t * 5.0) * 10 * t;
  }
  const topY = ch * 0.10;
  const spanY = ch - topY;

  // ---------------- banks earth base (soft, painted) ----------------
  // valley fill with correlated noise
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(0, ch);
  ctx.lineTo(0, topY * 0.3);
  for (let i = 0; i <= 90; i++) {
    const t = i / 90;
    const y = topY * 0.3 + t * (ch - topY * 0.3);
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    const wobble = (fbm(t * 6, 3.4, 3) - 0.5) * 50 * (0.3 + t);
    ctx.lineTo(cx - hw - 60 - (1 - t) * 40 + wobble, y);
  }
  ctx.lineTo(0, ch);
  ctx.closePath();
  const gLeft = ctx.createLinearGradient(0, topY * 0.3, 0, ch);
  gLeft.addColorStop(0, '#8a7248');
  gLeft.addColorStop(0.35, '#5e4a2a');
  gLeft.addColorStop(0.7, '#382a18');
  gLeft.addColorStop(1, '#1c140a');
  ctx.fillStyle = gLeft;
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(cw, ch);
  ctx.lineTo(cw, topY * 0.3);
  for (let i = 90; i >= 0; i--) {
    const t = i / 90;
    const y = topY * 0.3 + t * (ch - topY * 0.3);
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    const wobble = (fbm(t * 6 + 7, 5.4, 3) - 0.5) * 50 * (0.3 + t);
    ctx.lineTo(cx + hw + 60 + (1 - t) * 40 + wobble, y);
  }
  ctx.lineTo(cw, ch);
  ctx.closePath();
  const gRight = ctx.createLinearGradient(cw, topY * 0.3, cw, ch);
  gRight.addColorStop(0, '#8a7248');
  gRight.addColorStop(0.35, '#5a4729');
  gRight.addColorStop(0.7, '#352818');
  gRight.addColorStop(1, '#1a120a');
  ctx.fillStyle = gRight;
  ctx.fill();
  ctx.restore();

  // mossy / grassy patches on banks (irregular blobs, not circles)
  function blobPath(cx, cy, r, seed, jitter) {
    ctx.beginPath();
    const N = 10;
    for (let j = 0; j <= N; j++) {
      const a = (j / N) * Math.PI * 2;
      const rr = r * (0.6 + noise2(seed + j * 0.9, cy * 0.01) * 0.8);
      const px = cx + Math.cos(a) * rr;
      const py = cy + Math.sin(a) * rr * 0.7;
      if (j === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
      if (jitter) { /* keeps loop simple */ }
    }
    ctx.closePath();
  }
  for (let i = 0; i < 220; i++) {
    const t = 0.1 + rand() * 0.9;
    const side = rand() < 0.5 ? -1 : 1;
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    // place on the bank (outside water)
    const off = hw + 10 + rand() * 350;
    const x = cx + side * off;
    const y = topY + t * spanY;
    if (x < 0 || x > cw) continue;
    const r = 8 + rand() * 34;
    const bright = rand();
    const baseG = 55 + bright * 60;
    ctx.fillStyle = `rgba(${52 + bright * 55},${baseG},${28 + bright * 30},${0.28 + rand() * 0.35})`;
    blobPath(x, y, r, x * 0.05 + y * 0.03, 0);
    ctx.fill();
  }
  // grass tufts along banks
  for (let i = 0; i < 900; i++) {
    const t = 0.08 + rand() * 0.92;
    const side = rand() < 0.5 ? -1 : 1;
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    const off = hw + 2 + rand() * 80;
    const x = cx + side * off;
    const y = topY + t * spanY + (rand() - 0.5) * 6;
    if (x < 0 || x > cw) continue;
    const h = 4 + rand() * (10 + t * 18);
    const g = 70 + rand() * 60;
    ctx.strokeStyle = `rgba(${60 + rand() * 50},${g},${25 + rand() * 30},${0.5 + rand() * 0.4})`;
    ctx.lineWidth = 0.7 + rand() * 1.5;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + (rand() - 0.5) * 8, y - h * 0.6, x + (rand() - 0.5) * 14, y - h);
    ctx.stroke();
  }

  // ---------------- stream water ----------------
  ctx.save();
  ctx.beginPath();
  const waterPts = [];
  for (let i = 0; i <= 100; i++) {
    const t = i / 100;
    const y = topY + t * spanY;
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    waterPts.push({ y, lx: cx - hw, rx: cx + hw, t });
  }
  ctx.moveTo(waterPts[0].lx, waterPts[0].y);
  for (let i = 0; i < waterPts.length; i++) ctx.lineTo(waterPts[i].lx, waterPts[i].y);
  for (let i = waterPts.length - 1; i >= 0; i--) ctx.lineTo(waterPts[i].rx, waterPts[i].y);
  ctx.closePath();
  ctx.clip();

  const wg = ctx.createLinearGradient(0, topY, 0, ch);
  wg.addColorStop(0, '#d9c190');
  wg.addColorStop(0.25, '#9a8a66');
  wg.addColorStop(0.6, '#5b5a54');
  wg.addColorStop(1, '#333a3c');
  ctx.fillStyle = wg;
  ctx.fillRect(0, 0, cw, ch);

  // reflection streaks following the wind, uneven
  for (let i = 0; i < 260; i++) {
    const t = rand();
    const y = topY + t * spanY;
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    const x = cx + (rand() - 0.5) * hw * 1.9;
    const w = hw * (0.03 + rand() * 0.18);
    const h = 1 + rand() * (2 + t * 5);
    const amber = rand() > 0.3;
    ctx.globalAlpha = 0.12 + rand() * 0.3;
    ctx.fillStyle = amber ? '#e8b96a' : '#8a9db0';
    ctx.fillRect(x - w / 2, y, w, h);
  }
  ctx.globalAlpha = 1;

  // ripples short and following curve
  for (let i = 0; i < 1800; i++) {
    const t = rand();
    const y = topY + t * spanY;
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    const spread = Math.pow(rand(), 0.7);
    const side = rand() < 0.5 ? -1 : 1;
    const x = cx + side * spread * hw;
    const len = (2 + rand() * 6) * (0.4 + t * 2.0);
    // ripples follow water curve, so add small tangent slant based on local slope
    const slope = (streamCenter(Math.min(1, t + 0.01)) - streamCenter(Math.max(0, t - 0.01))) * 0.5;
    const col = rand();
    let c;
    if (col < 0.42) c = `rgba(240,200,130,${0.22 + rand() * 0.35})`;
    else if (col < 0.8) c = `rgba(150,168,180,${0.18 + rand() * 0.32})`;
    else c = `rgba(90,80,55,${0.28 + rand() * 0.35})`;
    ctx.strokeStyle = c;
    ctx.lineWidth = 0.6 + rand() * (0.6 + t * 1.8);
    ctx.beginPath();
    ctx.moveTo(x - len / 2, y);
    ctx.quadraticCurveTo(x, y + slope * 0.3 + (rand() - 0.5) * 1.5, x + len / 2, y);
    ctx.stroke();
  }

  // shimmer
  for (let i = 0; i < 130; i++) {
    const t = Math.pow(rand(), 1.5);
    const y = topY + t * spanY;
    const cx = streamCenter(t);
    const hw = streamHalf(t);
    const x = cx + (rand() - 0.5) * hw * 1.6;
    const len = 4 + rand() * (10 + t * 30);
    ctx.strokeStyle = `rgba(255,240,200,${0.18 + rand() * 0.35})`;
    ctx.lineWidth = 0.8 + rand() * 1.8;
    ctx.beginPath();
    ctx.moveTo(x - len / 2, y);
    ctx.lineTo(x + len / 2, y);
    ctx.stroke();
  }

  ctx.restore();

  // ---------------- partially submerged rocks ----------------
  function drawRockInWater(cx, cy, w, h, depth) {
    // shadow on water
    ctx.save();
    ctx.fillStyle = 'rgba(20,18,14,0.35)';
    ctx.beginPath();
    ctx.ellipse(cx, cy + h * 0.35, w * 1.15, h * 0.45, 0, 0, Math.PI * 2);
    ctx.fill();
    // body — irregular silhouette
    ctx.beginPath();
    const segs = 16;
    for (let i = 0; i <= segs; i++) {
      const a = Math.PI + (i / segs) * Math.PI; // upper half (above water)
      const rr = 1 + (hash2(cx * 0.1 + i * 3.1, cy * 0.1) - 0.5) * 0.4;
      const px = cx + Math.cos(a) * w * rr;
      const py = cy + Math.sin(a) * h * rr;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    // base at waterline, irregular
    for (let i = segs; i >= 0; i--) {
      const a = (i / segs) * Math.PI;
      const rr = 1 + (hash2(cx * 0.2 + i * 4.7, cy) - 0.5) * 0.3;
      const px = cx - Math.cos(a) * w * rr;
      const py = cy + Math.sin(a) * h * 0.35 * rr;
      ctx.lineTo(px, py);
    }
    ctx.closePath();
    const g = ctx.createLinearGradient(cx - w, cy - h, cx + w, cy + h);
    g.addColorStop(0, '#9a9488');
    g.addColorStop(0.4, '#5e5a52');
    g.addColorStop(1, '#2e2a24');
    ctx.fillStyle = g;
    ctx.fill();
    // rim light
    ctx.strokeStyle = 'rgba(240,220,170,0.3)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.arc(cx - w * 0.2, cy - h * 0.4, Math.min(w, h) * 0.6, Math.PI * 1.1, Math.PI * 1.65);
    ctx.stroke();
    // moss patches on top
    for (let i = 0; i < 14; i++) {
      const mx = cx + (rand() - 0.5) * w * 1.3;
      const my = cy - h * (0.2 + rand() * 0.5);
      const mr = 2 + rand() * 5;
      ctx.fillStyle = `rgba(${70 + rand() * 30},${90 + rand() * 40},${40 + rand() * 25},${0.5 + rand() * 0.4})`;
      ctx.beginPath();
      ctx.ellipse(mx, my, mr, mr * 0.65, rand(), 0, Math.PI * 2);
      ctx.fill();
    }
    // occlusion ripple line where rock meets water
    ctx.strokeStyle = 'rgba(20,30,35,0.5)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.ellipse(cx, cy + h * 0.32, w * 1.05, h * 0.3, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }
  drawRockInWater(cw * 0.40, ch * 0.58, 24, 14, 0.3);
  drawRockInWater(cw * 0.60, ch * 0.70, 42, 26, 0.4);
  drawRockInWater(cw * 0.47, ch * 0.86, 68, 40, 0.6);
  drawRockInWater(cw * 0.66, ch * 0.92, 50, 30, 0.7);
  drawRockInWater(cw * 0.52, ch * 0.48, 14, 8, 0.2);

  // ---------------- trees: tapering irregular silhouettes, branching ----------------
  function drawBranch(x, y, ang, len, wdt, depth, col) {
    if (depth <= 0) return;
    const ex = x + Math.cos(ang) * len;
    const ey = y + Math.sin(ang) * len;
    const mx = x + Math.cos(ang + 0.25) * len * 0.55;
    const my = y + Math.sin(ang + 0.25) * len * 0.55;
    ctx.strokeStyle = col;
    ctx.lineWidth = wdt;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(mx, my, ex, ey);
    ctx.stroke();
    // sub-branches
    const nSub = depth > 1 ? 2 : 1;
    for (let i = 0; i < nSub; i++) {
      const angOut = ang + (rand() - 0.5) * 1.4;
      drawBranch(ex, ey, angOut, len * (0.55 + rand() * 0.15), wdt * 0.6, depth - 1, col);
    }
  }
  function drawCanopyTrunk(tr) {
    const haze = tr.d;
    const N = 24;
    const left = [], right = [];
    // base is off-screen below
    const baseY = ch + 60;
    const topYt = tr.top; // continues past top edge
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const y = baseY + (topYt - baseY) * t;
      const taper = tr.w * (1 - t * 0.65);
      const sway = Math.sin(t * 4.5 + tr.x * 0.02) * tr.w * 0.25 + tr.lean * (baseY - y);
      const ccx = tr.x + sway;
      const fw = (hash2(i * 1.7, tr.x * 0.1) - 0.5) * taper * 0.18;
      left.push({ x: ccx - taper / 2 + fw, y });
      right.push({ x: ccx + taper / 2 + (hash2(i * 2.3, tr.x * 0.1 + 9) - 0.5) * taper * 0.18, y });
    }
    // paint trunk body
    ctx.save();
    ctx.beginPath();
    for (let i = 0; i < left.length; i++) {
      if (i === 0) ctx.moveTo(left[i].x, left[i].y);
      else ctx.lineTo(left[i].x, left[i].y);
    }
    for (let i = right.length - 1; i >= 0; i--) ctx.lineTo(right[i].x, right[i].y);
    ctx.closePath();
    const baseR = Math.round(70 + (1 - haze) * 30);
    const baseG = Math.round(54 + (1 - haze) * 20);
    const baseB = Math.round(36 + (1 - haze) * 12);
    const gx = ctx.createLinearGradient(tr.x - tr.w, 0, tr.x + tr.w, 0);
    gx.addColorStop(0, `rgb(${baseR + 50},${baseG + 36},${baseB + 22})`);
    gx.addColorStop(0.35, `rgb(${baseR + 10},${baseG + 5},${baseB + 2})`);
    gx.addColorStop(0.75, `rgb(${baseR - 20},${baseG - 15},${baseB - 8})`);
    gx.addColorStop(1, `rgb(${baseR - 35},${baseG - 26},${baseB - 14})`);
    ctx.fillStyle = gx;
    ctx.fill();
    // clip for details
    ctx.clip();

    // vertical bark fissures
    for (let i = 0; i < 120 * (1 - haze); i++) {
      const t = rand();
      const idx = Math.floor(t * N);
      const y = left[idx].y;
      const lxx = left[idx].x, rxx = right[idx].x;
      const x = lxx + rand() * (rxx - lxx);
      const len = 20 + rand() * 100 * (1 - haze);
      const darkShade = rand() > 0.35;
      ctx.strokeStyle = darkShade
        ? `rgba(28,18,10,${0.35 + rand() * 0.4})`
        : `rgba(${170 + rand() * 50},${140 + rand() * 30},${95},${0.15 + rand() * 0.2})`;
      ctx.lineWidth = 0.6 + rand() * 2.2;
      ctx.beginPath();
      ctx.moveTo(x, y - len * 0.5);
      let px = x, py = y - len * 0.5;
      const steps = 4;
      for (let s = 0; s < steps; s++) {
        px += (rand() - 0.5) * tr.w * 0.12;
        py += len / steps;
        ctx.lineTo(px, py);
      }
      ctx.stroke();
    }
    // knots
    for (let k = 0; k < 2 + Math.floor((1 - haze) * 4); k++) {
      const t = 0.15 + rand() * 0.75;
      const ky = left[Math.floor(t * N)].y;
      const lxx = left[Math.floor(t * N)].x;
      const rxx = right[Math.floor(t * N)].x;
      const kx = lxx + (0.25 + rand() * 0.5) * (rxx - lxx);
      const kr = 4 + rand() * (1 - haze) * 14;
      ctx.fillStyle = `rgba(30,18,10,${0.6 + rand() * 0.3})`;
      ctx.beginPath();
      ctx.ellipse(kx, ky, kr, kr * 1.5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = `rgba(120,85,50,${0.4})`;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.ellipse(kx, ky, kr * 1.35, kr * 1.8, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    // mottling
    for (let i = 0; i < 260 * (1 - haze); i++) {
      const t = rand();
      const idx = Math.floor(t * N);
      const y = left[idx].y + (rand() - 0.5) * 40;
      const lxx = left[idx].x, rxx = right[idx].x;
      const x = lxx + rand() * (rxx - lxx);
      ctx.fillStyle = `rgba(${100 + rand() * 60},${80 + rand() * 50},${55 + rand() * 40},${0.12 + rand() * 0.2})`;
      ctx.fillRect(x, y, 1 + rand() * 2.5, 2 + rand() * 6);
    }
    // haze overlay far
    if (haze > 0.35) {
      ctx.fillStyle = `rgba(210,185,140,${(haze - 0.35) * 0.5})`;
      ctx.fillRect(0, 0, cw, ch);
    }
    ctx.restore();

    // branches at upper part
    const branchCol = `rgb(${baseR - 5},${baseG - 5},${baseB - 3})`;
    const nb = 2 + Math.floor((1 - haze) * 3);
    for (let i = 0; i < nb; i++) {
      const t = 0.4 + rand() * 0.55;
      const idx = Math.floor(t * N);
      const bx = (left[idx].x + right[idx].x) * 0.5;
      const by = left[idx].y;
      const dir = rand() < 0.5 ? -1 : 1;
      drawBranch(bx, by, dir * (0.6 + rand() * 0.8) - Math.PI * 0.5, 60 + rand() * 90, 4 + tr.w * 0.18, 3, branchCol);
    }
  }

  const trunks = [
    { x: cw * 0.06, top: -40, w: 130, lean: 0.03, d: 0.06 },
    { x: cw * 0.94, top: -60, w: 150, lean: -0.03, d: 0.06 },
    { x: cw * 0.18, top: -60, w: 80, lean: 0.04, d: 0.25 },
    { x: cw * 0.82, top: -40, w: 95, lean: -0.04, d: 0.28 },
    { x: cw * 0.30, top: -20, w: 40, lean: 0.02, d: 0.5 },
    { x: cw * 0.70, top: -30, w: 46, lean: -0.02, d: 0.55 },
    { x: cw * 0.40, top: -20, w: 22, lean: 0.01, d: 0.75 },
    { x: cw * 0.63, top: -20, w: 24, lean: -0.01, d: 0.78 }
  ];
  trunks.sort((a, b) => b.d - a.d);
  for (const tr of trunks) drawCanopyTrunk(tr);

  // ---------------- foliage: clustered leaves, multiple scales ----------------
  function drawLeafStroke(x, y, size, angle, col) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.fillStyle = col;
    const s = size;
    ctx.beginPath();
    ctx.moveTo(-s, 0);
    ctx.quadraticCurveTo(0, -s * 0.55, s, 0);
    ctx.quadraticCurveTo(0, s * 0.55, -s, 0);
    ctx.fill();
    ctx.restore();
  }
  const palettes = [
    { a: [195, 140, 55], b: [225, 178, 92] },
    { a: [180, 100, 45], b: [215, 138, 72] },
    { a: [120, 120, 55], b: [158, 152, 82] },
    { a: [150, 58, 42], b: [178, 80, 58] },
    { a: [165, 122, 60], b: [200, 160, 92] },
    { a: [210, 160, 60], b: [235, 195, 105] }
  ];
  function leafColor(i, bright) {
    const p = palettes[i % palettes.length];
    const f = bright ? 0.55 + rand() * 0.45 : 0.2 + rand() * 0.5;
    return `rgb(${Math.round(p.a[0] + (p.b[0] - p.a[0]) * f)},${Math.round(p.a[1] + (p.b[1] - p.a[1]) * f)},${Math.round(p.a[2] + (p.b[2] - p.a[2]) * f)})`;
  }
  function leafCluster(cx, cy, rx, ry, count, depth, brightness) {
    for (let i = 0; i < count; i++) {
      const ang = rand() * Math.PI * 2;
      const rad = Math.pow(rand(), 0.6);
      const x = cx + Math.cos(ang) * rad * rx;
      const y = cy + Math.sin(ang) * rad * ry;
      const pi = Math.floor(rand() * palettes.length);
      const size = (3 + rand() * 7) * (1 - depth * 0.5);
      const a = (rand() - 0.5) * Math.PI + (rand() > 0.5 ? 0.3 : -0.3);
      let col = leafColor(pi, brightness);
      ctx.globalAlpha = depth > 0.3 ? (1 - depth * 0.55) : 1;
      drawLeafStroke(x, y, size, a, col);
      ctx.globalAlpha = 1;
    }
  }

  // far canopy (soft, upper region)
  for (let i = 0; i < 55; i++) {
    const x = rand() * cw;
    const y = ch * 0.02 + rand() * ch * 0.30;
    const rx = 40 + rand() * 110;
    const ry = 30 + rand() * 80;
    leafCluster(x, y, rx, ry, 70, 0.7, false);
  }
  // mid canopy
  for (let i = 0; i < 30; i++) {
    const x = rand() * cw;
    const y = ch * 0.12 + rand() * ch * 0.42;
    const rx = 50 + rand() * 90;
    const ry = 35 + rand() * 60;
    leafCluster(x, y, rx, ry, 110, 0.4, true);
  }
  // near foliage clusters at top edge + corners
  leafCluster(cw * 0.04, ch * 0.10, 130, 200, 220, 0.1, true);
  leafCluster(cw * 0.96, ch * 0.10, 150, 220, 240, 0.1, true);
  leafCluster(cw * 0.14, ch * 0.02, 140, 120, 200, 0.12, true);
  leafCluster(cw * 0.88, ch * 0.04, 150, 130, 220, 0.12, true);
  leafCluster(cw * 0.32, ch * 0.02, 120, 100, 160, 0.22, true);
  leafCluster(cw * 0.68, ch * 0.03, 120, 100, 160, 0.22, true);
  leafCluster(cw * 0.50, ch * 0.0, 120, 80, 150, 0.3, true);
  // soften joins mid-scene
  leafCluster(cw * 0.20, ch * 0.32, 120, 100, 140, 0.3, false);
  leafCluster(cw * 0.80, ch * 0.30, 130, 110, 160, 0.3, false);

  // ---------------- dappled light ----------------
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < 60; i++) {
    const t = rand();
    const x = cw * 0.15 + (rand() - 0.5) * cw * 0.7 + t * cw * 0.25;
    const y = ch * 0.05 + t * ch * 0.75;
    const r = 20 + rand() * 90;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(255,225,150,${0.07 + rand() * 0.13})`);
    g.addColorStop(1, 'rgba(255,200,120,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  // warm shaft from upper-left
  ctx.translate(cw * 0.20, ch * 0.02);
  ctx.rotate(0.5);
  const shaft = ctx.createLinearGradient(0, 0, 0, ch * 1.15);
  shaft.addColorStop(0, 'rgba(255,230,160,0.16)');
  shaft.addColorStop(0.5, 'rgba(255,215,140,0.05)');
  shaft.addColorStop(1, 'rgba(255,215,140,0)');
  ctx.fillStyle = shaft;
  ctx.fillRect(-90, 0, 220, ch * 1.15);
  ctx.restore();

  // ---------------- glowing distant opening ----------------
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const open = ctx.createRadialGradient(cw * 0.50, ch * 0.18, 10, cw * 0.50, ch * 0.18, ch * 0.45);
  open.addColorStop(0, 'rgba(255,245,200,0.80)');
  open.addColorStop(0.4, 'rgba(250,225,165,0.35)');
  open.addColorStop(1, 'rgba(250,225,165,0)');
  ctx.fillStyle = open;
  ctx.fillRect(0, 0, cw, ch);
  ctx.restore();

  // ---------------- vignette ----------------
  const vg = ctx.createRadialGradient(cw * 0.5, ch * 0.45, ch * 0.35, cw * 0.5, ch * 0.5, ch * 0.9);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(10,8,5,0.42)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, cw, ch);

  // foreground floating leaves for depth
  for (let i = 0; i < 30; i++) {
    const x = rand() * cw;
    const y = ch * 0.5 + rand() * ch * 0.5;
    const pi = Math.floor(rand() * palettes.length);
    const s = 4 + rand() * 8;
    ctx.globalAlpha = 0.85;
    drawLeafStroke(x, y, s, rand() * Math.PI * 2, leafColor(pi, rand() > 0.4));
    ctx.globalAlpha = 1;
  }
})();
